<template>
  <section class="workspace-page space-y-5">
    <header class="flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between"><div><h1 class="text-3xl font-extrabold tracking-[-.025em]">Analytics</h1><p class="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">Understand sales, order activity, product demand, expenses, and booking volume using only recorded business data.</p></div><form class="flex flex-wrap items-end gap-2" @submit.prevent="load"><label class="text-xs font-bold text-muted-foreground">From<Input v-model="dateFrom" class="mt-1" type="date" /></label><label class="text-xs font-bold text-muted-foreground">To<Input v-model="dateTo" class="mt-1" type="date" /></label><Button type="submit" :disabled="loading">{{ loading ? 'Refreshing…' : 'Apply range' }}</Button></form></header>

    <StatePanel v-if="loading" kind="loading" title="Calculating analytics" message="Aggregating actual sales, products, payments, bookings, and expenses." />
    <StatePanel v-else-if="error" kind="error" title="Analytics unavailable" :message="error"><Button variant="outline" type="button" @click="load">Try again</Button></StatePanel>

    <template v-else-if="report">
      <dl class="grid grid-cols-2 overflow-hidden rounded-xl border bg-card xl:grid-cols-4"><div v-for="metric in metrics" :key="metric.label" class="border-b p-4 [&:nth-child(odd)]:border-r [&:nth-last-child(-n+2)]:border-b-0 sm:p-5 xl:border-b-0 xl:border-r xl:last:border-r-0"><div class="flex items-center justify-between gap-3"><dt class="text-sm font-semibold text-muted-foreground">{{ metric.label }}</dt><span class="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-secondary text-primary"><component :is="metric.icon" class="h-4 w-4" aria-hidden="true" /></span></div><dd class="mt-3 text-2xl font-extrabold tabular-nums">{{ metric.value }}</dd><p class="mt-1 text-xs text-muted-foreground">{{ metric.detail }}</p></div></dl>

      <div class="grid gap-6 xl:grid-cols-[minmax(0,1.55fr)_minmax(20rem,.75fr)]">
        <section class="rounded-xl border bg-card p-5 sm:p-6"><RevenueChart title="Revenue by day" :description="`${rangeLabel} · cancelled orders excluded`" :points="salesPoints" :currency="business.activeBusiness?.currency" /></section>
        <section class="rounded-xl border bg-card p-5 sm:p-6" aria-labelledby="status-heading"><h2 id="status-heading" class="text-base font-extrabold">Order status</h2><p class="mt-1 text-sm text-muted-foreground">Distribution for {{ orders.length }} order{{ orders.length === 1 ? '' : 's' }}</p><div v-if="orders.length" class="mt-6 space-y-5"><div v-for="status in statusBreakdown" :key="status.key"><div class="flex items-center justify-between gap-4 text-sm"><span class="font-semibold capitalize">{{ status.label }}</span><span class="font-bold tabular-nums">{{ status.count }}</span></div><div class="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div class="h-full rounded-full bg-[var(--brand-primary)]" :style="{ width: `${status.percent}%`, opacity: status.opacity }" /></div></div></div><div v-else class="mt-6 border-y py-10 text-center"><p class="font-bold">No order activity</p><p class="mt-2 text-sm text-muted-foreground">Status distribution will appear after your first order.</p></div></section>
      </div>

      <div class="grid gap-6 xl:grid-cols-[minmax(0,1fr)_minmax(19rem,.55fr)]">
        <section class="rounded-xl border bg-card" aria-labelledby="product-performance-heading"><div class="border-b px-5 py-4"><h2 id="product-performance-heading" class="text-base font-extrabold">Product performance</h2><p class="mt-1 text-xs text-muted-foreground">Units and sales recorded in order snapshots</p></div><div v-if="topProducts.length" class="overflow-x-auto"><Table class="w-full min-w-[38rem] text-left text-sm"><TableHeader class="bg-muted/45 text-xs text-muted-foreground"><TableRow><TableHead class="px-5 py-3 font-bold">Product or service</TableHead><TableHead class="px-4 py-3 text-right font-bold">Units</TableHead><TableHead class="px-4 py-3 text-right font-bold">Orders</TableHead><TableHead class="px-5 py-3 text-right font-bold">Sales</TableHead></TableRow></TableHeader><TableBody class="divide-y"><TableRow v-for="item in topProducts" :key="item.name"><TableCell class="px-5 py-4 font-bold">{{ item.name }}</TableCell><TableCell class="px-4 py-4 text-right tabular-nums">{{ item.quantity }}</TableCell><TableCell class="px-4 py-4 text-right tabular-nums">{{ item.orders }}</TableCell><TableCell class="px-5 py-4 text-right font-bold tabular-nums">{{ money(item.sales) }}</TableCell></TableRow></TableBody></Table></div><div v-else class="px-5 py-12 text-center"><p class="font-bold">No product sales in this range</p><p class="mt-2 text-sm text-muted-foreground">Completed and active orders will populate this ranking.</p></div></section>

        <aside class="rounded-xl border bg-[var(--brand-secondary)] p-5 text-white sm:p-6" aria-labelledby="summary-heading"><h2 id="summary-heading" class="text-base font-extrabold">Performance summary</h2><p class="mt-1 text-sm text-white/55">{{ report.basis }}</p><dl class="mt-5 divide-y divide-white/10"><div v-for="item in summary" :key="item.label" class="flex items-center justify-between gap-4 py-3"><dt class="text-sm text-white/60">{{ item.label }}</dt><dd class="font-bold tabular-nums">{{ item.value }}</dd></div></dl><p class="mt-5 border-t border-white/10 pt-5 text-xs leading-5 text-white/50">Operational analytics are not accounting statements or forecasts. Values change only when actual records change.</p></aside>
      </div>
    </template>
  </section>
</template>

<script setup>
import { Banknote, BarChart3, ReceiptText, WalletCards } from 'lucide-vue-next'
const business = useBusinessStore(); const { apiFetch } = useApiClient(); const today = new Date(); const dateTo = ref(localDateKey(today)); const dateFrom = ref(localDateKey(new Date(today.getFullYear(), today.getMonth(), 1))); const report = ref(null); const orders = ref([]); const loading = ref(true); const error = ref('')
const rangeLabel = computed(() => `${shortDate(dateFrom.value)}–${shortDate(dateTo.value)}`)
const metrics = computed(() => [
  { label: 'Gross sales', value: money(report.value.sales), detail: `${report.value.orders.total} orders recorded`, icon: Banknote },
  { label: 'Gross profit', value: money(report.value.gross_profit), detail: 'Sales less recorded product costs', icon: BarChart3 },
  { label: 'Expenses', value: money(report.value.expenses), detail: 'Expenses incurred in this range', icon: ReceiptText },
  { label: 'Net operating result', value: money(report.value.net_operating_result), detail: 'Gross profit less expenses', icon: WalletCards },
])
const summary = computed(() => [
  { label: 'Average order', value: money(report.value.orders.total ? Number(report.value.sales) / report.value.orders.total : 0) },
  { label: 'Paid orders', value: report.value.orders.paid },
  { label: business.activeBusiness?.industry_preset === 'restaurant' ? 'Reservations' : 'Bookings', value: report.value.bookings.total },
  { label: 'Confirmed bookings', value: report.value.bookings.confirmed },
  { label: 'Inventory at cost', value: money(report.value.inventory.value_at_cost) },
  { label: 'Low-stock items', value: report.value.inventory.low_stock_items },
  { label: 'Open invoices', value: report.value.invoice_aging.open_count },
])
const salesPoints = computed(() => { const start = new Date(`${dateFrom.value}T12:00:00`); const end = new Date(`${dateTo.value}T12:00:00`); const byDate = new Map(); const dayCount = Math.min(92, Math.max(1, Math.round((end - start) / 86400000) + 1)); for (let index = 0; index < dayCount; index += 1) { const date = new Date(start); date.setDate(start.getDate() + index); const key = date.toISOString().slice(0, 10); byDate.set(key, { key, label: new Intl.DateTimeFormat('en-PH', { month: 'short', day: 'numeric' }).format(date), fullLabel: new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium' }).format(date), value: 0 }) } orders.value.filter((order) => order.status !== 'cancelled').forEach((order) => { const point = byDate.get(order.placed_at?.slice(0, 10)); if (point) point.value += Number(order.grand_total || 0) }); return [...byDate.values()] })
const statusBreakdown = computed(() => { const keys = ['pending', 'confirmed', 'processing', 'fulfilled', 'completed', 'cancelled']; return keys.map((key, index) => { const count = orders.value.filter((order) => order.status === key).length; return { key, label: key.replaceAll('_', ' '), count, percent: orders.value.length ? Math.max(3, Math.round((count / orders.value.length) * 100)) : 0, opacity: String(1 - index * 0.1) } }).filter((item) => item.count) })
const topProducts = computed(() => { const products = new Map(); orders.value.filter((order) => order.status !== 'cancelled').forEach((order) => { (order.items || []).forEach((line) => { const item = products.get(line.name) || { name: line.name, quantity: 0, orders: 0, sales: 0 }; item.quantity += Number(line.quantity || 0); item.orders += 1; item.sales += Number(line.line_total || 0); products.set(line.name, item) }) }); return [...products.values()].sort((a, b) => b.sales - a.sales).slice(0, 8) })
watch(() => business.activeBusiness?.public_id, load); onMounted(async () => { if (!business.activeBusiness) await business.loadBusinesses(); await load() })
async function load() { if (!business.activeBusiness) return; loading.value = true; error.value = ''; try { const id = business.activeBusiness.public_id; const [reportResponse, orderResponse] = await Promise.all([apiFetch(`businesses/${id}/reports/?date_from=${dateFrom.value}&date_to=${dateTo.value}`), apiFetch(`businesses/${id}/orders/?page_size=100`)]); report.value = reportResponse; orders.value = (orderResponse.results || []).filter((order) => order.placed_at?.slice(0, 10) >= dateFrom.value && order.placed_at?.slice(0, 10) <= dateTo.value) } catch (requestError) { error.value = requestError?.data?.error?.message || 'PixelCore could not calculate analytics for this date range.' } finally { loading.value = false } }
function money(value) { return new Intl.NumberFormat('en-PH', { style: 'currency', currency: business.activeBusiness?.currency || 'PHP', maximumFractionDigits: 0 }).format(Number(value || 0)) }
function shortDate(value) { return new Intl.DateTimeFormat('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(`${value}T12:00:00`)) }
function localDateKey(value) { const offset = value.getTimezoneOffset(); return new Date(value.getTime() - offset * 60000).toISOString().slice(0, 10) }
</script>
